SELECT 
FROM orders
WHERE user_id = #{userId} AND request_id = #{requestId}

SELECT 
FROM orders
WHERE order_no = #{orderNo} AND user_id = #{userId}

SELECT 
FROM orders
WHERE user_id = #{userId}
ORDER BY id DESC
LIMIT #{offset}, #{size}

SELECT FROM orders WHERE user_id = #{userId}
ORDER BY created_at ASC, id ASC ORDER BY total_amount DESC, id DESC ORDER BY total_amount ASC, id ASC ORDER BY created_at DESC, id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM orders
WHERE user_id = #{userId}

SELECT COUNT(*) AS orderCount,
       COALESCE(SUM(t.item_count), 0) AS itemCount,
       COALESCE(SUM(t.total_amount), 0) AS totalAmount
FROM (
    SELECT o.id, o.total_amount,
           COALESCE(SUM(oi.quantity), 0) AS item_count
    FROM orders o
    LEFT JOIN order_item oi ON oi.order_id = o.id
    WHERE o.user_id = #{userId}
      AND o.paid_at IS NOT NULL

        AND o.status = #{status}


        AND o.paid_at >= #{start}


        AND o.paid_at < #{end}


        AND EXISTS (
            SELECT 1 FROM order_item k
            WHERE k.order_id = o.id
              AND LOCATE(#{keyword}, k.product_name) > 0
        )

    GROUP BY o.id, o.total_amount
) t

SELECT 
FROM orders


        status = #{status}


ORDER BY id DESC
LIMIT #{offset}, #{size}

SELECT 
FROM orders
WHERE status = 'PENDING_PAYMENT' AND created_at < #{cutoff}
ORDER BY id
LIMIT #{limit}

