UPDATE orders
SET status = 'SHIPPED', shipped_at = NOW(3), tracking_no = #{trackingNo}
WHERE order_no = #{orderNo} AND status = 'PACKING'

UPDATE orders
SET status = #{status}
WHERE order_no = #{orderNo}
  AND status IN ('REFUND_REQUESTED', 'RETURN_REQUESTED')
